
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../core/widgets/n_card.dart';
import '../../../core/theme/app_colors.dart';
import '../../../data/models/app_models.dart';
import '../providers/finance_provider.dart';
class DebtsScreen extends ConsumerWidget { const DebtsScreen({super.key}); @override Widget build(BuildContext context, WidgetRef ref){ final debts=ref.watch(debtsProvider); return Scaffold(appBar: AppBar(title: const Text('الديون')), body: ListView.builder(padding: const EdgeInsets.all(16), itemCount: debts.length, itemBuilder: (_,i){ final d=debts[i]; return Padding(padding: const EdgeInsets.only(bottom:12), child: NCard(child: Row(children:[CircleAvatar(backgroundColor: d.type=='owe'? Colors.red.withOpacity(0.12): AppColors.secondary.withOpacity(0.12), child: Icon(d.type=='owe'? Icons.arrow_upward: Icons.arrow_downward, color: d.type=='owe'? Colors.red: AppColors.secondary)), const SizedBox(width:12), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children:[Text(d.person, style: const TextStyle(fontWeight: FontWeight.w800)), Text(d.dueDate.toString().split(' ')[0], style: const TextStyle(fontSize:12, color:Colors.grey))])), Text('\${d.amount.toStringAsFixed(0)}', style: const TextStyle(fontWeight: FontWeight.w900))] ))); }), floatingActionButton: FloatingActionButton(backgroundColor:AppColors.secondary, foregroundColor:Colors.white, onPressed: ()=>_add(context, ref), child: const Icon(Icons.add))); } void _add(BuildContext ctx, WidgetRef ref){ final p=TextEditingController(); final a=TextEditingController(); showDialog(context: ctx, builder: (_)=> AlertDialog(title: const Text('دين جديد'), content: Column(mainAxisSize:MainAxisSize.min, children:[TextField(controller:p, decoration: const InputDecoration(labelText:'الشخص')), TextField(controller:a, keyboardType: TextInputType.number, decoration: const InputDecoration(labelText:'المبلغ'))]), actions:[TextButton(onPressed: ()=>Navigator.pop(ctx), child: const Text('إلغاء')), ElevatedButton(onPressed:(){ final d=DebtModel.create(p.text, double.tryParse(a.text)??0); ref.read(debtsProvider.notifier).add(d); Navigator.pop(ctx);}, child: const Text('إضافة'))])); } }
